export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  let init = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let dxEst = 0, dyEst = 0, dzEst = 0;
  let kThrust = 21.4, mEst = 0.725, mot = 0.45;
  let lastThrust = 0.45, lastRoll = 0, lastPitch = 0;
  let cmdRollF = 0, cmdPitchF = 0, rollOff = 0, pitchOff = 0, yawInt = 0;
  let targetIndex = -1, phase = 'align', settle = 0;
  let prevGateX = -10, prevGateY = 1.05, prevGateZ = -0.85;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;
      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = sp * cr, bodyZ = -sr;
      const ux = cy * bodyX + sy * bodyZ;
      const uy = cp * cr;
      const uz = -sy * bodyX + cy * bodyZ;

      if (!init) {
        init = true;
        px = p.x; py = p.y; pz = p.z;
        vx = 0; vy = 0; vz = 0;
      } else {
        mot += (lastThrust - mot) * 0.22;
        cmdRollF += (lastRoll - cmdRollF) * 0.20;
        cmdPitchF += (lastPitch - cmdPitchF) * 0.20;

        const drag = 0.42 / mEst;
        const axK = kThrust * mot * ux - drag * vx;
        const ayK = kThrust * mot * uy - drag * vy - 9.81;
        const azK = kThrust * mot * uz - drag * vz;

        px += (vx + 0.5 * (axK + dxEst) * 0.01) * 0.01;
        py += (vy + 0.5 * (ayK + dyEst) * 0.01) * 0.01;
        pz += (vz + 0.5 * (azK + dzEst) * 0.01) * 0.01;
        vx += (axK + dxEst) * 0.01;
        vy += (ayK + dyEst) * 0.01;
        vz += (azK + dzEst) * 0.01;

        const epx = p.x - px, epy = p.y - py, epz = p.z - pz;
        const evx = v.x - vx, evy = v.y - vy, evz = v.z - vz;

        px += 0.65 * epx + 0.003 * evx;
        py += 0.65 * epy + 0.003 * evy;
        pz += 0.65 * epz + 0.003 * evz;
        vx += 12.0 * epx + 0.45 * evx;
        vy += 12.0 * epy + 0.45 * evy;
        vz += 12.0 * epz + 0.45 * evz;

        if (py > 0.09) {
          dxEst = clamp(dxEst + 12.0 * epx + 20.0 * evx, -8.5, 8.5);
          dyEst = clamp(dyEst + 12.0 * epy + 20.0 * evy, -6.0, 6.0);
          dzEst = clamp(dzEst + 12.0 * epz + 20.0 * evz, -8.5, 8.5);
          if (mot * uy > 0.28) {
            kThrust = clamp(kThrust + 0.35 * dyEst * 0.01 / (mot * uy), 16.5, 27.0);
            dyEst *= 0.985;
            mEst = clamp(15.5 / kThrust, 0.60, 0.85);
          }
          const rErr = (att.roll + 0.206 * rates.roll) - cmdRollF;
          const pErr = (att.pitch + 0.206 * rates.pitch) - cmdPitchF;
          rollOff = clamp(rollOff + 0.12 * (rErr - rollOff), -0.28, 0.28);
          pitchOff = clamp(pitchOff + 0.12 * (pErr - pitchOff), -0.28, 0.28);
        } else {
          py = p.y;
          vy = Math.max(0, v.y);
        }
      }

      let tx, ty, tz, vxDes = 0, vyDes = 0, vzDes = 0;
      let kpX = 6.5, kdX = 4.2, kpY = 8.0, kdY = 4.8, kpZ = 8.5, kdZ = 5.0;
      let maxTilt = 0.55;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          if (targetIndex >= 0) {
            const gPrev = targetIndex === 0 ? { x: -1.15, y: 1.05, z: -0.85 }
              : targetIndex === 1 ? { x: 0.15, y: 1.40, z: 0.25 }
              : { x: 1.35, y: 1.05, z: 1.05 };
            prevGateX = gPrev.x; prevGateY = gPrev.y; prevGateZ = gPrev.z;
          }
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }

        if (phase === 'align') {
          tx = gate.x - 0.26;
          ty = gate.y;
          tz = gate.z;
          // If still clearing previous gate plane, keep y/z near previous gate until x is clear
          if (px < prevGateX + 0.14) {
            ty = prevGateY;
            tz = prevGateZ;
          }
          const errY = Math.abs(ty - py), errZ = Math.abs(tz - pz), errX = Math.abs(tx - px);
          const spdYZ = Math.hypot(vy, vz), spdX = Math.abs(vx);
          if (errZ < 0.048 && errY < 0.08 && errX < 0.10 && spdYZ < 0.18 && spdX < 0.25) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 6) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          const remX = gate.x - px;
          const tRem = clamp(remX / Math.max(vx, 0.25), 0.04, 0.35);
          const zPred = pz + vz * tRem;
          const yPred = py + vy * tRem;
          // Abort crossing if lateral/vertical alignment is threatened before reaching point of no return
          if (remX > 0.055 && (Math.abs(pz - gate.z) > 0.072 || Math.abs(zPred - gate.z) > 0.082 ||
              Math.abs(py - gate.y) > 0.14 || Math.abs(yPred - gate.y) > 0.16)) {
            phase = 'align';
            settle = 0;
            tx = gate.x - 0.26;
            ty = gate.y;
            tz = gate.z;
            kpX = 9.0; kdX = 5.5;
          } else {
            tx = gate.x + 0.22;
            ty = gate.y;
            tz = gate.z;
            vxDes = 0.70;
            kpZ = 11.0; kdZ = 6.0;
            kpY = 10.0; kdY = 5.5;
          }
        }
      } else {
        if (targetIndex !== 3) {
          targetIndex = 3;
          prevGateX = 1.35; prevGateY = 1.05; prevGateZ = 1.05;
          phase = 'pad_approach';
          settle = 0;
        }
        const pad = obs.pad.centre;
        const distXZ = Math.hypot(pad.x - px, pad.z - pz);
        const spdXZ = Math.hypot(vx, vz);

        if (phase === 'pad_approach') {
          tx = pad.x;
          tz = pad.z;
          ty = px < prevGateX + 0.14 ? prevGateY : 0.45;
          if (px < prevGateX + 0.14) tz = prevGateZ;
          if (distXZ < 0.09 && spdXZ < 0.22 && py < 0.60) {
            phase = 'descend';
          }
        }
        if (phase === 'descend') {
          tx = pad.x;
          tz = pad.z;
          if (distXZ > 0.12) {
            ty = Math.max(py, 0.18);
          } else {
            ty = 0.05;
            vyDes = py > 0.18 ? -0.35 : -0.15;
          }
          if (py < 0.15) {
            maxTilt = 0.14;
          }
          if (py <= 0.082 && distXZ <= 0.11 && spdXZ < 0.25) {
            lastThrust = 0;
            lastRoll = 0;
            lastPitch = 0;
            return { thrust: 0, roll: 0, pitch: 0, yawRate: 0 };
          }
        }
      }

      // Limit position error so distant targets produce smooth cruise speed instead of huge tilt
      const ex = tx - px, ey = ty - py, ez = tz - pz;
      const distXZ = Math.hypot(ex, ez);
      const maxStepXZ = phase === 'cross' ? 0.50 : 0.38;
      const scaleXZ = distXZ > maxStepXZ ? maxStepXZ / distXZ : 1.0;
      const exC = ex * scaleXZ;
      const ezC = ez * scaleXZ;
      const eyC = clamp(ey, -0.35, 0.40);

      let axDes = kpX * exC + kdX * (vxDes - vx);
      let azDes = kpZ * ezC + kdZ * (vzDes - vz);
      let ayDes = kpY * eyC + kdY * (vyDes - vy);

      // Strong safety barrier: never cross nextGate.x unless in 'cross' phase or well aligned
      if (obs.gateIndex < 3 && phase !== 'cross') {
        const gate = obs.nextGate.centre;
        const marginX = (gate.x - 0.16) - (px + 0.22 * vx);
        if (marginX < 0) {
          axDes = Math.min(axDes, 14.0 * marginX - 4.0 * vx);
        }
      }

      axDes = clamp(axDes, -5.5, 5.5);
      azDes = clamp(azDes, -5.5, 5.5);
      ayDes = clamp(ayDes, -4.5, 5.5);

      const drag = 0.42 / mEst;
      const fx = axDes - dxEst + drag * vx;
      const fy = Math.max(1.5, 9.81 + ayDes - dyEst + drag * vy);
      const fz = azDes - dzEst + drag * vz;

      const fbx = cy * fx - sy * fz;
      const fbz = sy * fx + cy * fz;

      const desPitch = Math.atan2(fbx, fy);
      const desRoll = -Math.atan2(fbz, Math.hypot(fbx, fy));

      const pitch = clamp(desPitch - pitchOff, -maxTilt, maxTilt);
      const roll = clamp(desRoll - rollOff, -maxTilt, maxTilt);
      const thrust = clamp(fy / (kThrust * Math.max(0.55, uy)), 0.05, 1.0);

      yawInt = clamp(yawInt + att.yaw * 0.01, -0.4, 0.4);
      const yawRate = clamp(-4.5 * att.yaw - 10.0 * yawInt - 0.4 * rates.yaw, -2, 2);

      lastThrust = thrust;
      lastRoll = roll;
      lastPitch = pitch;

      return { thrust, roll, pitch, yawRate };
    },
  };
}

