import { Worker, isMainThread, parentPort, workerData } from "node:worker_threads";
import { runTrial } from "./tasks/drone/sim.mjs";

if (isMainThread) {
  const total = 400;
  const workers = 8;
  const perWorker = total / workers;
  let done = 0, passed = 0, maxPad = 0, maxTime = 0;
  const promises = [];
  for (let w = 0; w < workers; w++) {
    promises.push(new Promise((resolve) => {
      const worker = new Worker(new URL(import.meta.url), {
        workerData: { start: 1000 + w * perWorker, count: perWorker }
      });
      worker.on("message", (res) => {
        for (const r of res) {
          done++;
          if (r.success) {
            passed++;
            if (r.landingError > maxPad) maxPad = r.landingError;
            if (r.simulatedSeconds > maxTime) maxTime = r.simulatedSeconds;
          } else {
            console.log("FAIL:", r);
          }
        }
        resolve();
      });
    }));
  }
  await Promise.all(promises);
  console.log(`Total: ${passed}/${done} passed, maxPad=${maxPad}, maxTime=${maxTime}`);
} else {
  const { start, count } = workerData;
  const out = [];
  for (let i = 0; i < count; i++) {
    const { result } = await runTrial("/workspace/controller.js", start + i);
    out.push(result);
  }
  parentPort.postMessage(out);
}
